-- Nové fotky lekcí BOSU, Individuální trénink a DeepWork na přání studia (schváleno 26. 11. 2026): stejný sál jako u ostatních
-- lekcí (okna s matným sklem a tmavě zelené pruhy, světlá podlaha), teplý tón a štítek OCTOPUSH s názvem lekce. Vytvořené
-- pomocí AI. Fotka se vymění jen při prvním spuštění (dokud obrázek není mezi nahranými); fotku, kterou studio později
-- vybere v Admin → Lekce, opakované spuštění nepřepíše. Dosavadní obrázky zůstávají mezi nahranými.

-- 1) Lekce dostanou nové fotky.
-- BOSU – ženy dělají dřep na modrých BOSU
UPDATE "class_types" SET "image_url" = '/media/4ff2a409-72db-49c6-a00c-87c0112813fb.webp'
WHERE ("slug" ILIKE 'bosu%' OR "name" ILIKE 'BOSU%')
  AND NOT EXISTS (SELECT 1 FROM "media" WHERE "id" = '4ff2a409-72db-49c6-a00c-87c0112813fb');
--> statement-breakpoint
-- Individuální trénink – trenérka opravuje klientce dřep s jednoručkou
UPDATE "class_types" SET "image_url" = '/media/4f9694f1-5754-48b1-adb6-0123a68847c2.webp'
WHERE ("slug" ILIKE 'individual%' OR "name" ILIKE 'Individuální%')
  AND NOT EXISTS (SELECT 1 FROM "media" WHERE "id" = '4f9694f1-5754-48b1-adb6-0123a68847c2');
--> statement-breakpoint
-- DeepWork – výpad s kolenem na podložce a rukama nad hlavou, jen s vlastní vahou
UPDATE "class_types" SET "image_url" = '/media/0fe2a225-f66c-4c7c-aa3b-0765f3ff109b.webp'
WHERE ("slug" ILIKE 'deep%work%' OR "name" ILIKE 'Deep%work%')
  AND NOT EXISTS (SELECT 1 FROM "media" WHERE "id" = '0fe2a225-f66c-4c7c-aa3b-0765f3ff109b');
--> statement-breakpoint
