-- 3) Vytvořené pomocí AI: stejné označení (vodoznak chobotnice s „AI“) jako ostatní AI fotky.
UPDATE "settings" SET "value" = (SELECT jsonb_agg(x ORDER BY x) FROM (SELECT DISTINCT jsonb_array_elements_text("value" || '["/media/0fe2a225-f66c-4c7c-aa3b-0765f3ff109b.webp", "/media/4f9694f1-5754-48b1-adb6-0123a68847c2.webp", "/media/4ff2a409-72db-49c6-a00c-87c0112813fb.webp"]'::jsonb) x) s)
WHERE "key" = 'aiImages' AND jsonb_typeof("value") = 'array' AND NOT "value" @> '["/media/0fe2a225-f66c-4c7c-aa3b-0765f3ff109b.webp", "/media/4f9694f1-5754-48b1-adb6-0123a68847c2.webp", "/media/4ff2a409-72db-49c6-a00c-87c0112813fb.webp"]'::jsonb;
